from datetime import date, timedelta
from typing import List, Optional, Dict, Set

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # Track used leave days per employee per year: {employee: {year: days_used}}
        self.used_days: Dict[str, Dict[int, int]] = {}

    def _is_weekend(self, d: date) -> bool:
        """Check if date is Saturday (5) or Sunday (6)"""
        return d.weekday() >= 5

    def _is_holiday(self, d: date) -> bool:
        """Check if date is in the holidays set"""
        return d in self.holidays

    def _count_business_days(self, start: date, end: date) -> int:
        """Count business days (excluding weekends and holidays) between start and end (inclusive)"""
        if start > end:
            raise ValueError("End date cannot be before start date")

        count = 0
        current = start
        while current <= end:
            if not self._is_weekend(current) and not self._is_holiday(current):
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        # Requirement 1: end date before start date
        if end < start:
            raise ValueError("End date cannot be before start date")

        # Calculate business days in the requested period
        business_days = self._count_business_days(start, end)

        # Get the year for this request (use the year of the start date, but validate against today's year for eligibility)
        year = start.year

        # Check if employee has enough remaining days for this year
        used_so_far = self.used_days.get(employee, {}).get(year, 0)
        remaining = self.days_per_year - used_so_far

        if business_days > remaining:
            raise ValueError("Not enough remaining leave days")

        # Record the used days
        if employee not in self.used_days:
            self.used_days[employee] = {}
        self.used_days[employee][year] = used_so_far + business_days

        return business_days

    def remaining(self, employee: str, year: int) -> int:
        """Return remaining leave days for the employee in the given year."""
        used_so_far = self.used_days.get(employee, {}).get(year, 0)
        return max(0, self.days_per_year - used_so_far)
